      "arFull": "اِنَّ هٰذَا الْقُرْاٰنَ یَهْدِیْ لِلَّتِیْ هِیَ اَقْوَمُ وَیُبَشِّرُ الْمُؤْمِنِیْنَ الَّذِیْنَ یَعْمَلُوْنَ الصّٰلِحٰتِ اَنَّ لَهُمْ اَجْرًا كَبِیْرًا ۟ۙ",
