      "number": 47,
      "arFull": "نَحْنُ اَعْلَمُ بِمَا یَسْتَمِعُوْنَ بِهٖۤ اِذْ یَسْتَمِعُوْنَ اِلَیْكَ وَاِذْ هُمْ نَجْوٰۤی اِذْ یَقُوْلُ الظّٰلِمُوْنَ اِنْ تَتَّبِعُوْنَ اِلَّا رَجُلًا مَّسْحُوْرًا ۟",
