      "arFull": "وَاِذْ قُلْنَا لِلْمَلٰٓىِٕكَةِ اسْجُدُوْا لِاٰدَمَ فَسَجَدُوْۤا اِلَّاۤ اِبْلِیْسَ ؕ قَالَ ءَاَسْجُدُ لِمَنْ خَلَقْتَ طِیْنًا ۟ۚ",
